+}
+
+#[test]
+fn a_question_without_an_answer_is_missing() {
+    let questions = asked().with("also", Noul::new("And this?"));
+    let error = documented().check_against(&questions).unwrap_err();
+    assert!(matches!(error, Error::MissingAnswer { id } if id == "also"));
